    logLevel: "error",
    configFile: false,
    plugins: [
      // Tailwind emits only the classes it finds; point it at the workspace too.
      { name: "workspace-source", enforce: "pre", transform: (code, id) => (id.endsWith("/src/index.css") ? `${code}\n@source "${ws}/Page.tsx";\n` : null) },
