import fs from "node:fs"
import path from "node:path"
import http from "node:http"
import { chromium } from "playwright-core"

const OUT = path.resolve(".build")
const MIME = { ".png": "image/png", ".svg": "image/svg+xml", ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".woff2": "font/woff2" }
const server = http.createServer((req, res) => {
  const p = path.join(OUT, decodeURIComponent(new URL(req.url, "http://x").pathname))
  if (!p.startsWith(OUT) || !fs.existsSync(p) || fs.statSync(p).isDirectory()) return res.writeHead(404).end()
  res.writeHead(200, { "content-type": MIME[path.extname(p)] ?? "application/octet-stream" })
  fs.createReadStream(p).pipe(res)
})
await new Promise((r) => server.listen(0, "127.0.0.1", r))
const url = `http://127.0.0.1:${server.address().port}/index.html`
const browser = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH ?? "/opt/pw-browsers/chromium" })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto(url)
await page.waitForFunction(() => window.__READY__ === true, null, { timeout: 30000 })

const out = await page.evaluate(() => {
  const r = (el) => { const b = el.getBoundingClientRect(); return { l: Math.round(b.left), r: Math.round(b.right), t: Math.round(b.top), w: Math.round(b.width), h: Math.round(b.height) } }
  const cs = (el, p) => getComputedStyle(el)[p]
  const res = {}
  const tables = [...document.querySelectorAll("[data-slot=custom-table]")]
  res.captions = tables.map((t) => {
    const cap = t.querySelector("[data-slot=table-caption]")
    const table = t.querySelector("table")
    return cap ? { cap: r(cap), table: r(table), textAlign: cs(cap, "textAlign") } : null
  })
  const rule = document.querySelector("[data-slot=rule] [data-slot=separator]")
  res.rule = rule ? { rect: r(rule), h: cs(rule, "height"), bg: cs(rule, "backgroundColor") } : null
  const row = document.querySelector("[data-slot=table-row]")
  res.tableRowBorder = row ? cs(row, "borderBottomWidth") : null
  res.progress = [...document.querySelectorAll("[data-slot=progress]")].map((p) => ({ h: cs(p, "height"), track: cs(p, "backgroundColor") }))
  res.progressIndicator = [...document.querySelectorAll("[data-slot=progress-indicator]")].map((p) => cs(p, "backgroundColor"))
  const strip = document.querySelector("[data-slot=figure-strip]")
  const sb = strip ? strip.querySelector("[data-slot=scroll-area-scrollbar][data-orientation=horizontal]") : null
  res.strip = strip ? { rect: r(strip), scrollbar: sb ? { rect: r(sb), state: sb.getAttribute("data-state"), opacity: cs(sb, "opacity") } : "none", type: strip.getAttribute("data-radix-scroll-area-viewport") ? "?" : "?" } : null
  const grid = document.querySelector("[data-slot=figure-grid]")
  const gimg = grid ? grid.querySelector("[data-slot=figure-image]") : null
  res.grid = grid && gimg ? { grid: r(grid), img: r(gimg) } : null
  const figStripImg = strip ? strip.querySelector("[data-slot=figure-image]") : null
  res.stripImg = figStripImg ? r(figStripImg) : null
  return res
})
console.log(JSON.stringify(out, null, 1))
await browser.close()
server.close()

